    /// The one exit, main thread, at most once.
    private func report(_ result: Result<URL, any Error>) {
        DispatchQueue.main.async { [weak self] in
            guard let self = self, let completion = self.completion else { return }
            self.completion = nil
            completion(result)
        }
    }

