import AVFoundation
import CoreMedia
import VideoToolbox

/// A WebM or Matroska file opened by a built-in rewrap (spec §11 #216-R):
/// the core indexes the container (`ReelContainer`) and its first video and
/// audio streams are copied, unchanged, into a QuickTime movie under
/// `~/Library/Application Support/Frame Job/Rewrapped/`, the folder ffmpeg's
/// conversions use, by `FFmpegRewrap.destination(for:)`'s digest name — so a
/// second import of the same file reuses the copy.
///
/// The order is the decision's: the core opens the file; a codec this Mac
/// cannot decode is refused in #216's sentence BEFORE anything is copied
/// (VP8, AV1 without hardware decode, VP9 Profile 1 or 3), and a codec the
/// copy cannot carry is refused in its own (`unsupported`), which alone
/// falls through to the opt-in ffmpeg step; the video is snapped to its
/// frame grid when it lies on one; the copy's size is checked against the
/// free space first; and the movie is written under a `.partial.mov` name
/// and moved into place, so a failure leaves no file behind.
///
/// Await-free (spec §11 W-8): `ContainerRewrapWriter` waits on its writer
/// through a semaphore.
enum ContainerRewrap {

    /// Whether `url` begins with an EBML header: 1A 45 DF A3.
    static func isMatroska(_ url: URL) -> Bool {
        guard let handle = try? FileHandle(forReadingFrom: url) else { return false }
        defer { try? handle.close() }
        let head = (try? handle.read(upToCount: 4)) ?? Data()
        return head == Data([0x1A, 0x45, 0xDF, 0xA3])
    /// writes it, signals, and never touches it again; the waiter reads it
    /// only after the wait returns.
    final class ProbeBox: @unchecked Sendable {
        var outcome: Result<MediaDescriptor, any Error>?
    }

    /// Whether the codec carries alpha. The format description's own flag
    /// first (ProRes 4444 and animation-with-alpha set it); the codec type is
    /// the fallback for files whose writer omitted the extension.
    static func hasAlphaChannel(_ descriptions: [CMFormatDescription]) -> Bool {
        for description in descriptions {
            if let flag = CMFormatDescriptionGetExtension(
                description, extensionKey: kCMFormatDescriptionExtension_ContainsAlphaChannel)
                as? Bool, flag {
                return true
            }
            switch CMFormatDescriptionGetMediaSubType(description) {
            // 'ap4h' ProRes 4444, 'ap4x' ProRes 4444 XQ, 'rle ' animation.
            case 0x6170_3468, 0x6170_3478, 0x726C_6520:
                return true
            default:
                continue
            }
        }
        return false
    }
}

//! The Cluster walk (spec §11 #216-R): every frame of the two tracks
//! `container.rs` picked, as an index entry — where its bytes are, how many,
//! its Block's time, its place in the Block's lace and whether it is a
//! keyframe. It reads element headers, Block headers and lace sizes, and
//! skips every payload unread.
//!
//! A Cluster of unknown size (a live recording's, written before its length
//! was known) ends at the next level-1 element. A SimpleBlock is a keyframe
//! by its flag; a BlockGroup's Block is one when the group holds no
//! ReferenceBlock. Xiph, EBML and fixed lacing are read. A frame of no bytes
//! is not indexed.
//!
//! **A damaged or truncated tail ends the index**: an element header that
//! cannot be read, a Block whose lace does not add up, or a payload running
//! past the end of the file stops the walk, and what was read before it is
//! kept — so a file cut off part-way imports shorter rather than not at all.

